// --- kod (dane TER wyżej) ---
// siatka: dwie kratki na bajt (starsze 4 bity = pierwsza), w kratce las*4+woda, poziomy 0–3 (pokrycie: brak · trochę · połowa · prawie całość)
let terG=null;
function terGrid(){if(terG)return terG;const b=atob(TER.g),n=TER.R*TER.C,g=new Uint8Array(n);
  for(let i=0;i<n;i++){const v=b.charCodeAt(i>>1);g[i]=i&1?v&15:v>>4}return terG=g}
// obrazek siatki (1 kratka = 1 piksel) — przeglądarka sama go wygładza przy powiększeniu, stąd miękkie plamy; adres blob: zamiast data: (krótki napis przy każdym odrysowaniu)
const terUrl={f:"",w:""};let terBusy=false;
function terPrep(){if(terBusy||terUrl.f)return;terBusy=true;try{const g=terGrid(),A=[0,90,170,255];
  ["f","w"].forEach(k=>{const c=document.createElement("canvas");c.width=TER.C;c.height=TER.R;const x=c.getContext("2d"),im=x.createImageData(TER.C,TER.R),d=im.data,
      rgb=k==="f"?[46,160,67]:[30,120,230];
    for(let i=0;i<g.length;i++){const l=k==="f"?g[i]>>2:g[i]&3;if(!l)continue;const j=i*4;d[j]=rgb[0];d[j+1]=rgb[1];d[j+2]=rgb[2];d[j+3]=A[l]}
    x.putImageData(im,0,0);c.toBlob(b=>{if(!b)return;terUrl[k]=URL.createObjectURL(b);if(terUrl.f&&terUrl.w&&typeof arRedraw==="function")arRedraw()},"image/png")})}catch(e){terBusy=false}}
let terRv=null;
function terRivers(){if(terRv)return terRv;terRv=TER.rv.map(s=>{const v=s.split(",").map(Number),out=[];let la=0,lo=0;
  for(let i=0;i+1<v.length;i+=2){la+=v[i];lo+=v[i+1];out.push([la/1e3,lo/1e3])}return {p:out}});return terRv}
// warstwa na radar: xy(lat,lon) z areaSvgIn, Z — przybliżenie (grubość linii stała na ekranie), off — ukryte rodzaje („f”, „w”, „r”)
function terSvg(xy,Z,off){terPrep();let s="";
  const p0=xy(TER.la,TER.lo),p1=xy(TER.la-TER.R*TER.dla,TER.lo+TER.C*TER.dlo);
  ["f","w"].forEach(k=>{if(off.has(k)||!terUrl[k])return;
    s+='<image class="arter '+k+'" href="'+terUrl[k]+'" x="'+(AR_CX+p0.x).toFixed(1)+'" y="'+(AR_CY+p0.y).toFixed(1)+'" width="'+(p1.x-p0.x).toFixed(1)+'" height="'+(p1.y-p0.y).toFixed(1)+'" preserveAspectRatio="none"/>'});
  if(!off.has("r"))s+='<path class="arriv" d="'+terRivers().map(r=>r.p.map((q,i)=>{const o=xy(q[0],q[1]);return (i?'L':'M')+(AR_CX+o.x).toFixed(1)+' '+(AR_CY+o.y).toFixed(1)}).join("")).join("")+'" style="stroke-width:'+(1.6/Z).toFixed(2)+'px"/>';
  return s?'<g clip-path="url(#arclip)">'+s+'</g>':""}
// najbliższy las / woda od środka okolicy: kratka z pokryciem co najmniej „połowa”; null — daleko (ponad 60 km) albo poza obszarem danych
function terNear(a,k){const g=terGrid(),r0=Math.floor((TER.la-a.lat)/TER.dla),c0=Math.floor((a.lon-TER.lo)/TER.dlo),kx=TER.dlo*111.2*Math.cos(a.lat*Math.PI/180),M=60;
  if(r0<-M||c0<-M||r0>=TER.R+M||c0>=TER.C+M)return null;let best=null,bd=1e9;
  for(let r=Math.max(0,r0-M);r<=Math.min(TER.R-1,r0+M);r++)for(let c=Math.max(0,c0-M);c<=Math.min(TER.C-1,c0+M);c++){const v=g[r*TER.C+c],l=k==="f"?v>>2:v&3;if(l<2)continue;
    const d=Math.hypot((r-r0)*TER.dla*111.2,(c-c0)*kx);if(d<bd){bd=d;best={lat:TER.la-(r+.5)*TER.dla,lon:TER.lo+(c+.5)*TER.dlo}}}
  return best&&bd<=M?best:null}
